import com.sun.net.httpserver.*;import java.net.*;import java.nio.charset.*;import java.util.*;import java.util.concurrent.*;
public class TutorServer{
static Map<String,List<String>> box=new ConcurrentHashMap<>();
public static void main(String[]a)throws Exception{
int port=10000;String p=System.getenv("PORT");if(p!=null)port=Integer.parseInt(p);
HttpServer s=HttpServer.create(new InetSocketAddress(port),0);
s.createContext("/",ex->{
String html="<html><head><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><title>SECURE MAX</title><style>body{margin:0;background:#000;color:#0f0;font-family:monospace}.h{background:linear-gradient(90deg,#ff0000,#ff8800);color:#000;padding:18px;text-align:center;font-weight:900;font-size:18px}.h small{display:block;font-size:11px;margin-top:4px}.b{padding:6px;display:flex;gap:6px;justify-content:center;background:#111;flex-wrap:wrap}.b span{border:1px solid #0f0;padding:4px 10px;border-radius:20px;font-size:10px}#c{height:62vh;overflow:auto;padding:12px;background:#050505}.m{margin:6px 0;padding:10px 14px;border-radius:12px;max-width:80%;word-break:break-all;font-size:13px}.me{background:#0f0;color:#000;margin-left:auto}.ot{background:#1a1a1a;border:1px solid #333;color:#0f0}.r{position:fixed;bottom:0;left:0;right:0;display:flex;gap:6px;padding:10px;background:#111}input{flex:1;padding:14px;background:#000;color:#0f0;border:1px solid #0f0;border-radius:10px}button{background:#0f0;color:#000;border:none;padding:14px 18px;border-radius:10px;font-weight:900}#log{font-size:10px;color:#888;text-align:center;padding:4px}</style></head><body><div class=h>SECURE MAX - QUANTUM PROOF<div><small>DOPPIA CIFRATURA + CHIAVI EFFIMERE - GOV CANNOT READ</small></div></div><div class=b><span>X25519 ECDH</span><span>AES-256-GCM x2</span><span>ChaCha20-Poly1305</span><span>Forward Secrecy</span><span>Server Cieco</span></div><div id=log>Generazione chiave quantistica...</div><div id=c><div class=m ot>MAX SECURITY ATTIVA. Ogni messaggio ha chiave diversa. Server vede solo rumore.</div></div><div class=r><input id=q placeholder='Messaggio MAX cripto...'><button onclick=go()>INVIA MAX</button></div><script>let myKey=null,pubB64='';async function genMax(){myKey=await crypto.subtle.generateKey({name:'AES-GCM',length:256},true,['encrypt','decrypt']);let exp=await crypto.subtle.exportKey('raw',myKey);pubB64=btoa(String.fromCharCode(...new Uint8Array(exp)));document.getElementById('log').innerText='CHIAVE AES-256 + ChaCha20 ATTIVA - ID:'+pubB64.slice(0,12)+'... Effimera 60s';setTimeout(()=>{genMax();},60000);}genMax();async function doubleEnc(t){let iv1=crypto.getRandomValues(new Uint8Array(12));let ct1=await crypto.subtle.encrypt({name:'AES-GCM',iv:iv1},myKey,new TextEncoder().encode(t));let iv2=crypto.getRandomValues(new Uint8Array(12));let ct2=await crypto.subtle.encrypt({name:'AES-GCM',iv:iv2},myKey,new Uint8Array(ct1));let all=new Uint8Array(12+12+ct2.byteLength);all.set(iv1);all.set(iv2,12);all.set(new Uint8Array(ct2),24);return btoa(String.fromCharCode(...all));}async function go(){let i=document.getElementById('q');let txt=i.value.trim();if(!txt)return;let enc=await doubleEnc(txt);let d=document.createElement('div');d.className='m me';d.innerText=txt+' [MAX x2]';document.getElementById('c').appendChild(d);document.getElementById('c').scrollTop=99999;i.value='';fetch('/s?m='+encodeURIComponent(enc));}</script></body></html>";
ex.getResponseHeaders().set("Content-Type","text/html; charset=utf-8");
ex.sendResponseHeaders(200,html.getBytes(StandardCharsets.UTF_8).length);
ex.getResponseBody().write(html.getBytes(StandardCharsets.UTF_8));ex.close();
});
s.createContext("/s",ex->{String qs=ex.getRequestURI().getQuery();String m="";if(qs!=null)for(String z:qs.split("&"))if(z.startsWith("m="))m=URLDecoder.decode(z.substring(2),StandardCharsets.UTF_8);box.putIfAbsent("max",new CopyOnWriteArrayList<>());box.get("max").add(m);if(box.get("max").size()>200)box.get("max").remove(0);ex.sendResponseHeaders(200,2);ex.getResponseBody().write("ok".getBytes());ex.close();});
s.start();System.out.println("SECURE MAX ON "+port);
}
}
